local function submitKey(key)
    key = M.cleanKey(key)
    if key == "" then
        Library:Notify({Title="⚠️ Nenhuma chave inserida", Description="Por favor, insira sua chave.", Time=3})
        return
    end
    Library:Notify({Title="🔑 Verificando", Description="Validando sua chave...", Time=2})

    -- NEW backend: validate the key + get this game's scripts in one call.
    local data, err = M.validateKeyNew(key)
    if type(data) ~= "table" then
        local msg = "Essa chave não é válida. Verifique e tente novamente."
        if err == "wrong_game" then
            msg = "Esta chave é para outro jogo. Obtenha uma chave para este jogo."
        elseif err == "network" or err == "no_request" then
            msg = "Erro de rede. Tente novamente."
        end
        Library:Notify({Title="❌ Chave inválida", Description=msg, Time=5})
        return
    end

    local scripts = data.scripts or {}
    if #scripts == 0 then
        Library:Notify({Title="🔓 Chave válida", Description="Ainda não há scripts definidos para este jogo.", Time=5})
        return
    end

    -- Valid — remember the key for next time, close this GUI, show the selector.
    M.saveKeyLocal(key)
    Library:Notify({
        Title = "🔓 Chave válida",
        Description = (#scripts == 1) and "Carregando script..." or "Escolha um script...",
        Time = 3,
    })
    task.wait(0.4)
    pcall(function() Library:Unload() end)
    M.showSelector(scripts)
end

local function readKeyFromBox()
    local raw
    pcall(function()
        local holder = Options and Options.KeyInput and Options.KeyInput.Holder
        local box = holder and holder:FindFirstChildOfClass("TextBox")
        if box then raw = box.Text end
    end)
    local key = M.cleanKey(raw)
    if key == "" then key = M.cleanKey(Options and Options.KeyInput and Options.KeyInput.Value) end
    if key == "" then key = M.cleanKey(keyInputValue) end
    return key
end

